import json, sys

# Load existing flow and IxP definition
with open('/work/output/artifacts/skill-flow-ixp-scaffold-multinode/ReceiptIntake/ReceiptIntake/ReceiptIntake.flow') as f:
    flow = json.load(f)

with open('/tmp/ixp_receipt.json') as f:
    ixp_data = json.load(f)

ixp_def = ixp_data['Data']['Node']
ixp_type = ixp_def['nodeType']
ixp_version = ixp_def['version']
ixp_out_def = ixp_def['outputDefinition']
ixp_defaults = ixp_def['inputDefaults']

# modelName fix: null → modelDisplayName
model_blob = dict(ixp_defaults.get('model', {}))
if not model_blob.get('modelName'):
    model_blob['modelName'] = model_blob.get('modelDisplayName', '')

# Script node definition (from registry get core.action.script)
script_def = {
  "nodeType": "core.action.script",
  "version": "1.0",
  "category": "data-operations",
  "description": "Run custom JavaScript code",
  "tags": ["code","javascript","python"],
  "sortOrder": 35,
  "supportsErrorHandling": True,
  "display": {"label": "Script","icon": "code"},
  "handleConfiguration": [
    {"position":"left","handles":[{"id":"input","type":"target","handleType":"input"}]},
    {"position":"right","handles":[
      {"id":"success","type":"source","handleType":"output"},
      {"id":"error","label":"Error","type":"source","handleType":"output",
       "visible":"{inputs.errorHandlingEnabled}","constraints":{"maxConnections":1}}
    ]}
  ],
  "debug": {"runtime":"clientScript"},
  "model": {"type":"bpmn:ScriptTask"},
  "inputDefinition": {
    "type":"object",
    "properties":{"script":{"type":"string","minLength":1,
      "errorMessage":"A script function is required","validationSeverity":"warning"}},
    "required":["script"]
  },
  "inputDefaults": {"script":""},
  "outputDefinition": {
    "output": {"type":"object","description":"The return value of the script",
      "source":"=result.response","var":"output"},
    "error": {"type":"object","description":"Error information if the node fails",
      "source":"=Error","var":"error",
      "schema":{"$schema":"http://json-schema.org/draft-07/schema#","type":"object",
        "required":["code","message","detail","category","status"],
        "properties":{"code":{"type":"string"},"message":{"type":"string"},
          "detail":{"type":"string"},"category":{"type":"string"},"status":{"type":"integer"}},
        "additionalProperties":False}}
  },
  "form": {"id":"script-properties","title":"Script configuration","sections":[
    {"id":"script","title":"Script","collapsible":True,"defaultExpanded":True,"fields":[
      {"name":"inputs.script","type":"custom","component":"script-editor",
       "componentProps":{"language":"javascript","returnType":"any","validationMode":"script","minHeight":200},
       "label":"Code","description":"JavaScript expression that returns a result object"}
    ]}
  ]}
}

# End node definition (from registry get core.control.end)
end_def = {
  "nodeType": "core.control.end",
  "version": "1.0",
  "category": "control-flow",
  "description": "Mark the end of a workflow path",
  "tags": ["control-flow","end","finish","complete"],
  "sortOrder": 20,
  "display": {"label":"End","icon":"circle-check","shape":"circle"},
  "handleConfiguration": [{"position":"left","handles":[{"id":"input","type":"target","handleType":"input"}]}],
  "model": {"type":"bpmn:EndEvent"},
  "runtimeConstraints": {"exclude":["api-function"]}
}

# Build nodes
nodes = [
    # Start node (existing — keep as-is)
    flow['nodes'][0],
    # IxP extraction node
    {
        "id": "extractReceipt",
        "type": ixp_type,
        "typeVersion": ixp_version,
        "display": {"label": "Extract Receipt (Receipt Model)"},
        "inputs": {
            "model": model_blob,
            "modelName": ixp_defaults.get('modelName', ''),
            "projectName": ixp_defaults.get('projectName', ''),
            "versionTag": "",
            "folderKey": ixp_defaults.get('folderKey', ''),
            "folderName": ixp_defaults.get('folderName', ''),
            "fileRef": "=js:$vars.start.output.document",
            "pageRange": "",
            "errorHandlingEnabled": True
        },
        "outputs": {
            "output": {
                "type": "object",
                "description": "Extraction result",
                "source": ixp_out_def['output']['source'],
                "var": "output"
            },
            "error": {
                "type": "object",
                "description": "Error information if extraction fails",
                "source": ixp_out_def['error']['source'],
                "var": "error"
            }
        }
    },
    # postReceipt script
    {
        "id": "postReceipt",
        "type": "core.action.script",
        "typeVersion": "1.0",
        "display": {"label": "postReceipt"},
        "inputs": {
            "script": "return { ok: \"OK\", result: $vars.extractReceipt.output };"
        },
        "outputs": {
            "output": {"type":"object","description":"Script return value","source":"=result.response","var":"output"},
            "error": {"type":"object","description":"Script error","source":"=Error","var":"error"}
        }
    },
    # sendToValidation script
    {
        "id": "sendToValidation",
        "type": "core.action.script",
        "typeVersion": "1.0",
        "display": {"label": "sendToValidation"},
        "inputs": {
            "script": "return { ok: \"OK\", result: $vars.extractReceipt.output };"
        },
        "outputs": {
            "output": {"type":"object","description":"Script return value","source":"=result.response","var":"output"},
            "error": {"type":"object","description":"Script error","source":"=Error","var":"error"}
        }
    },
    # logError script
    {
        "id": "logError",
        "type": "core.action.script",
        "typeVersion": "1.0",
        "display": {"label": "logError"},
        "inputs": {
            "script": "return { ok: \"OK\", error: $vars.extractReceipt.error };"
        },
        "outputs": {
            "output": {"type":"object","description":"Script return value","source":"=result.response","var":"output"},
            "error": {"type":"object","description":"Script error","source":"=Error","var":"error"}
        }
    },
    # End nodes
    {"id":"endPostReceipt","type":"core.control.end","typeVersion":"1.0","display":{"label":"End"},"inputs":{}},
    {"id":"endSendToValidation","type":"core.control.end","typeVersion":"1.0","display":{"label":"End"},"inputs":{}},
    {"id":"endLogError","type":"core.control.end","typeVersion":"1.0","display":{"label":"End"},"inputs":{}}
]

# Build edges
edges = [
    {"id":"edge-start-extract","sourceNodeId":"start","sourcePort":"output","targetNodeId":"extractReceipt","targetPort":"input"},
    {"id":"edge-extract-postReceipt","sourceNodeId":"extractReceipt","sourcePort":"success","targetNodeId":"postReceipt","targetPort":"input"},
    {"id":"edge-extract-sendToValidation","sourceNodeId":"extractReceipt","sourcePort":"success","targetNodeId":"sendToValidation","targetPort":"input"},
    {"id":"edge-extract-logError","sourceNodeId":"extractReceipt","sourcePort":"error","targetNodeId":"logError","targetPort":"input"},
    {"id":"edge-postReceipt-end","sourceNodeId":"postReceipt","sourcePort":"success","targetNodeId":"endPostReceipt","targetPort":"input"},
    {"id":"edge-sendToValidation-end","sourceNodeId":"sendToValidation","sourcePort":"success","targetNodeId":"endSendToValidation","targetPort":"input"},
    {"id":"edge-logError-end","sourceNodeId":"logError","sourcePort":"success","targetNodeId":"endLogError","targetPort":"input"}
]

# Build definitions: existing (manual trigger) + IxP + script + end
existing_defs = flow.get('definitions', [])
# Keep only core.trigger.manual, add the rest
defs_by_type = {d['nodeType']: d for d in existing_defs}
defs_by_type[ixp_type] = ixp_def
defs_by_type['core.action.script'] = script_def
defs_by_type['core.control.end'] = end_def
definitions = list(defs_by_type.values())

# Layout placeholder — format will overwrite
layout_nodes = {
    "start": {"position":{"x":200,"y":144},"size":{"width":96,"height":96},"collapsed":False},
    "extractReceipt": {"position":{"x":400,"y":144},"size":{"width":96,"height":96},"collapsed":False},
    "postReceipt": {"position":{"x":600,"y":50},"size":{"width":96,"height":96},"collapsed":False},
    "sendToValidation": {"position":{"x":600,"y":200},"size":{"width":96,"height":96},"collapsed":False},
    "logError": {"position":{"x":600,"y":350},"size":{"width":96,"height":96},"collapsed":False},
    "endPostReceipt": {"position":{"x":800,"y":50},"size":{"width":96,"height":96},"collapsed":False},
    "endSendToValidation": {"position":{"x":800,"y":200},"size":{"width":96,"height":96},"collapsed":False},
    "endLogError": {"position":{"x":800,"y":350},"size":{"width":96,"height":96},"collapsed":False}
}

# Assemble complete flow
out = {
    "id": flow['id'],
    "version": flow['version'],
    "name": flow['name'],
    "nodes": nodes,
    "edges": edges,
    "definitions": definitions,
    "bindings": flow.get('bindings', []),
    "variables": flow.get('variables', {}),
    "layout": {"nodes": layout_nodes}
}

with open('/work/output/artifacts/skill-flow-ixp-scaffold-multinode/ReceiptIntake/ReceiptIntake/ReceiptIntake.flow', 'w') as f:
    json.dump(out, f, indent=2)

print("OK - flow file written")
PYEOF

